package com.lovemaptually.entity;
import jakarta.persistence.*;import lombok.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.math.BigDecimal;import java.time.OffsetDateTime;import static com.lovemaptually.entity.Enums.*;
@Entity @Table(name="recommendation_requests") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class RecommendationRequest {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long requestId;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="group_id") private RelationGroup group;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="requested_by_user_id") private User requestedBy;@Column(nullable=false,columnDefinition="text") private String query;@Column(length=50) private String intentRegion;private Short intentCount;private Short intentBudget;private Integer candidateCount;@Column(precision=3,scale=2) private BigDecimal cfWeight;@Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="rec_status") private RecommendationStatus status;@org.hibernate.annotations.Generated(event=org.hibernate.generator.EventType.INSERT) @Column(nullable=false,insertable=false,updatable=false) private OffsetDateTime createdAt;private OffsetDateTime completedAt;}
